python3 << 'EOF'
import json
inv = json.load(open('/home/dev/garden/bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
print("top keys:", list(inv.keys()))
for r in inv.get("runs", []):
    print("\n== run:", r["run_id"], "arm:", r.get("arm"), "model:", r.get("model"))
    for k in list(r.keys())[:10]:
        v = r[k]
        if isinstance(v, dict) and (k=="steps"):
            for sk in sorted(v):
                t = v[sk]
                roles = {}
                for rec in t.get("tap_records", []):
                    roles[rec.get("role", "?")] = roles.get(rec.get("role","?"),0)+1
                print(f"  step{sk}: n_events={t.get('n_events')}, n_assistant={t.get('n_assistant_messages')}, tool_calls={t.get('tool_calls')}, tap_roles={roles}")
        elif isinstance(v, (list,)) and len(v) < 5:
            print(f"  {k}:", v)
        else:
            print(f"  {k}: {str(v)[:120]}")
EOF

